"use client";

import Image from "next/image";
import Link from "next/link";
import { useState } from "react";
import { formatMmk } from "@/lib/money-format";

export type NavKey = "games" | "wallet" | "deposit";

type LobbyHeaderProps = {
  active?: NavKey;
  balanceUsd?: string;
  mmkPerUsd?: string;
  onLogout?: () => void;
};

const NAV: { key: NavKey; label: string; href: string }[] = [
  { key: "games", label: "Games", href: "/games" },
  { key: "wallet", label: "Wallet", href: "/wallet" },
  { key: "deposit", label: "Deposit", href: "/deposit" },
];

export function LobbyHeader({
  active = "games",
  balanceUsd = "0",
  mmkPerUsd = "4500",
  onLogout,
}: LobbyHeaderProps) {
  const [hidden, setHidden] = useState(false);
  const mmk = formatMmk(balanceUsd, mmkPerUsd);

  return (
    <header className="w-full border-b border-[#d4af37]/20 bg-[linear-gradient(180deg,#021a12_0%,#01100b_100%)]">
      <div className="relative flex h-[72px] w-full items-center justify-between gap-3 px-3 sm:h-[80px] sm:px-4 lg:px-6">
        <Link href="/games" className="flex shrink-0 items-center gap-2.5 sm:gap-3">
          <span className="relative inline-flex">
            <span
              className="absolute inset-0 rounded-full bg-[#d4af37]/25 blur-md"
              aria-hidden
            />
            <Image
              src="/brand/sd-logo-circle.jpg"
              alt="Shwe Dunn"
              width={48}
              height={48}
              className="relative rounded-full border border-[#d4af37]/55 object-cover shadow-[0_0_18px_rgba(212,175,55,0.28)]"
              priority
            />
          </span>
          <p className="font-[family-name:var(--font-cinzel)] text-[1.1rem] font-semibold tracking-[0.14em] text-[#e8c547] sm:text-[1.35rem]">
            SHWE DUNN
          </p>
        </Link>

        <nav className="absolute left-1/2 hidden -translate-x-1/2 items-center gap-7 md:flex lg:gap-9">
          {NAV.map((item) => {
            const isActive = item.key === active;
            return (
              <Link
                key={item.key}
                href={item.href}
                className={`relative pb-1 text-[0.95rem] font-semibold tracking-[0.06em] transition ${
                  isActive
                    ? "text-[#e8c547]"
                    : "text-[#c5bba3] hover:text-[#e8c547]"
                }`}
              >
                {item.label}
                {isActive ? (
                  <span
                    className="absolute inset-x-0 -bottom-0.5 h-[2px] rounded-full bg-[#d4af37]"
                    aria-hidden
                  />
                ) : null}
              </Link>
            );
          })}
        </nav>

        <div className="flex shrink-0 items-center gap-2 sm:gap-2.5">
          <div className="flex items-center gap-2 rounded-full bg-[linear-gradient(180deg,#f0d78c_0%,#d4af37_55%,#b8922a_100%)] px-3.5 py-2 shadow-[0_6px_20px_rgba(212,175,55,0.28)] sm:gap-2.5 sm:px-4 sm:py-2.5">
            <p className="text-[0.95rem] font-extrabold tabular-nums tracking-wide text-[#1a1205] sm:text-[1.05rem]">
              {hidden ? "••••" : `${mmk} MMK`}
            </p>
            <button
              type="button"
              aria-label={hidden ? "Show balance" : "Hide balance"}
              onClick={() => setHidden((v) => !v)}
              className="text-[#1a1205]/80 hover:text-[#1a1205]"
            >
              <EyeIcon open={!hidden} />
            </button>
          </div>

          {onLogout ? (
            <button
              type="button"
              onClick={onLogout}
              className="hidden rounded-full border border-[#d4af37]/45 px-3.5 py-2 text-[0.78rem] font-semibold tracking-[0.08em] text-[#e8c547] transition hover:border-[#d4af37] hover:bg-[#d4af37]/10 sm:inline-flex"
            >
              Log out
            </button>
          ) : null}
        </div>
      </div>
    </header>
  );
}

function EyeIcon({ open }: { open: boolean }) {
  if (open) {
    return (
      <svg
        width="18"
        height="18"
        viewBox="0 0 24 24"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.8"
        aria-hidden
      >
        <path d="M3 12s3.5-6 9-6 9 6 9 6-3.5 6-9 6-9-6-9-6Z" />
        <circle cx="12" cy="12" r="2.5" />
      </svg>
    );
  }
  return (
    <svg
      width="18"
      height="18"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      aria-hidden
    >
      <path d="M3 12s3.5-6 9-6 9 6 9 6-3.5 6-9 6-9-6-9-6Z" />
      <path d="m4 4 16 16" />
    </svg>
  );
}
